#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("INVALID_INPUT");
        return 0;
    }
    const char *in = argv[1];
    size_t len = strlen(in);
    if (len == 0 || len > 31) {
        puts("INVALID_INPUT");
        return 0;
    }
    for (size_t i = 0; i < len; ++i) {
        if (in[i] != '0' && in[i] != '1') {
            puts("INVALID_INPUT");
            return 0;
        }
    }
    // Make a mutable copy for the tape/result
    char *tape = malloc(len + 1);
    if (!tape) return 1;
    memcpy(tape, in, len);
    tape[len] = '\0';

    // Perform binary increment using a Turing‑machine‑like algorithm.
    // Count steps as the number of head moves (left moves) performed.
    int steps = 0;
    // Start at the rightmost cell.
    ssize_t pos = (ssize_t)len - 1;
    // Move left, turning trailing '1's into '0's.
    while (pos >= 0 && tape[pos] == '1') {
        tape[pos] = '0';
        steps++;          // write/move left counted as a step
        pos--;
    }
    if (pos < 0) {
        // All bits were '1' -> overflow.
        puts("OVERFLOW");
        printf(" steps=%d\n", steps);
        free(tape);
        return 0;
    }
    // We found a '0' – turn it into '1'.
    tape[pos] = '1';
    steps++; // the final move/write

    // Output result.
    printf("result=%s\n", tape);
    printf(" steps=%d\n", steps);
    free(tape);
    return 0;
}
